-- T0B-13.C17 schema suite: homecollection catalogue properties (C17 05-SCHEMA Part A §1, §2, §4, §4.1, §4.2, §6; AC-0B-2.1, 2.2, 2.3, 2.4, 3.1, 3.2, 3.3, 3.4, 3.5, 3.6, 3.7, 4.1, 4.2, 4.3, 5.1, 5.2, 5.3, 6.1, 6.2, 6.3, 6.4).
-- Pure pg_catalog assertions: no fixtures, no data written. One rolled-back transaction. RLS is never disabled.
-- Run from the repo root: pg_prove -d <db> db/tests/homecollection/T0B-13.C17_schema.test.sql   (pgTAP in schema `extensions`; migrations + seeds loaded; superuser). NOT run in the unit-test environment (no database).
-- Markers (the node test checks them): C17 check 1 inventory / owner, 2 RLS ENABLE+FORCE (G exempt), 3 policy set + DELETE policy + owner policies, 4 grants, 5 indexes / constraints / FKs, 6 triggers + functions + audit,
-- 7 DEFINER inventory + FK direction (AC-0B-6.1 / 6.2 / 6.3), 8 views (none) + seeds (AC-0B-6.4). The FORCE-RLS tests T1..T5 of §4.2 live in T0B-13.C17_anonymise.test.sql of this directory.
-- Scope: homecollection.event_inbox is C0's (T0B-05) and excluded from every count. lims_api / lims_worker INHERIT lims_app, so "no DELETE" is asserted for lims_app only.
-- ACs: AC-0B-2.1 AC-0B-2.2 AC-0B-2.3 AC-0B-2.4 AC-0B-3.1 AC-0B-3.2 AC-0B-3.3 AC-0B-3.4 AC-0B-3.5 AC-0B-3.6 AC-0B-3.7 AC-0B-4.1 AC-0B-4.2 AC-0B-4.3 AC-0B-5.1 AC-0B-5.2 AC-0B-5.3 AC-0B-6.1 AC-0B-6.2 AC-0B-6.3 AC-0B-6.4
-- (2.x RLS/policies: checks 2-3; 3.x tenant isolation structure: checks 2, 5 + generated probes; 4.x grants/immutability: checks 4, 6; 5.x audit: check 6; 6.x order/FK/owner/views: checks 1, 7, 8)
BEGIN;
SET search_path = extensions, public, pg_catalog;
SELECT * FROM no_plan();

-- t: table; cls: §1 class; u: lims_app UPDATE; d: lims_app DELETE (visit_locations only); aud: audit trigger (class M / C); ce: centre-scoped (centre_id policy predicate)
CREATE TEMP TABLE rt(t, cls, u, d, aud, ce) AS VALUES
  ('settings','M',true,false,true,false),('booking_refs','M',true,false,true,false),('routes','M',true,false,true,true),('visits','C',true,false,true,true),('visit_transitions','A',false,false,false,true),
  ('visit_assignments','A',false,false,false,true),('visit_specimens','C',true,false,true,true),('devices','M',true,false,true,false),('sync_batches','A',false,false,false,false),('mutations','A',false,false,false,true),
  ('collections','C',true,false,true,true),('handovers','C',true,false,true,true),('handover_items','C',true,false,true,true),('visit_flags','C',true,false,true,true),('visit_locations','E',false,true,false,true);
CREATE TEMP TABLE rg(t) AS VALUES ('g_cs_reasons');

-- C17 check 1: inventory, owner (AC-0B-1.2, AC-0B-6.3), schema privileges, no sequences / enums / views
SELECT is((SELECT count(*)::int FROM pg_class c WHERE c.relnamespace = 'homecollection'::regnamespace AND c.relkind IN ('r','p')), 15 + 1 + 1, 'C17 check 1: homecollection holds 15 tenant + 1 G tables + event_inbox (16 chunk tables = 05-SCHEMA §4 count of table statements)');
SELECT is((SELECT array_agg(relname::text ORDER BY relname) FROM pg_class WHERE relnamespace = 'homecollection'::regnamespace AND relkind IN ('r','p') AND relname <> 'event_inbox'), (SELECT array_agg(t ORDER BY t) FROM (SELECT t FROM rt UNION ALL SELECT t FROM rg) x), 'C17 check 1: the table set equals the §1 / §4 inventory');
SELECT is((SELECT count(*)::int FROM pg_class c WHERE c.relnamespace = 'homecollection'::regnamespace AND c.relkind IN ('v','m')), 0, 'C17 check 1 / AC-0B-6.4: no view, no materialized view (IC §6 defines none; §1 "this chunk publishes none")');
SELECT is((SELECT count(*)::int FROM pg_class c WHERE c.relnamespace = 'homecollection'::regnamespace AND c.relkind = 'S'), 0, 'C17 check 1: no sequences');
SELECT is((SELECT count(*)::int FROM pg_type t WHERE t.typnamespace = 'homecollection'::regnamespace AND t.typtype = 'e'), 0, 'C17 check 1: no ENUM types');
SELECT is(pg_get_userbyid(c.relowner), 'lims_owner', 'C17 check 1: homecollection.' || c.relname || ' owned by lims_owner (AC-0B-1.2, AC-0B-6.3)') FROM pg_class c WHERE c.relnamespace = 'homecollection'::regnamespace AND c.relkind IN ('r','p');
SELECT is(has_schema_privilege('lims_app', 'homecollection', 'USAGE'), true, 'C17 check 1: lims_app has USAGE on schema homecollection');
SELECT is(has_schema_privilege(r, 'homecollection', 'CREATE'), false, 'C17 check 1: ' || r || ' cannot CREATE in homecollection') FROM unnest(ARRAY['lims_app','lims_api','lims_worker','lims_analytics']) r;

-- C17 check 2: RLS ENABLE + FORCE on the 15 tenant tables, none on the G table (AC-0B-2.1, 2.4)
SELECT is((SELECT relrowsecurity AND relforcerowsecurity FROM pg_class WHERE oid = ('homecollection.' || t)::regclass), true, 'C17 check 2 / AC-0B-2.1: ENABLE + FORCE RLS on homecollection.' || t) FROM rt;
SELECT is((SELECT relrowsecurity OR relforcerowsecurity FROM pg_class WHERE oid = ('homecollection.' || t)::regclass), false, 'C17 check 2 / AC-0B-2.1: homecollection.' || t || ' is RLS-exempt (global coded set, listed in rls_exempt.txt, D-130)') FROM rg;
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'homecollection' AND tablename = g.t), 0, 'C17 check 2: no policy on ' || g.t) FROM rg g;
SELECT is(NOT EXISTS (SELECT 1 FROM pg_class WHERE relnamespace = 'homecollection'::regnamespace AND relkind = 'r' AND relname NOT LIKE 'g\_%' AND NOT (relrowsecurity AND relforcerowsecurity)), true, 'C17 check 2 / AC-0B-2.4: every non-G homecollection table (incl. event_inbox) has ENABLE + FORCE RLS');
SELECT is((SELECT count(*)::int FROM information_schema.columns WHERE table_schema = 'homecollection' AND column_name = 'tenant_id' AND is_nullable = 'YES'), 0, 'C17 check 2 / AC-0B-3.5: tenant_id is NOT NULL everywhere');

-- C17 check 3: policies (AC-0B-2.3): 4 owner policies TO lims_owner; the one DELETE policy (visit_locations, system actor, expired rows); staff guard (P-16); tenant predicate; centre predicate with the ::uuid[] cast; no open predicate
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'homecollection' AND tablename <> 'event_inbox' AND roles = ARRAY['lims_app']::name[]), 41, 'C17 check 3 / §4.1: 41 lims_app policies (34 from the DO block + 6 handovers / handover_items + 1 DELETE)');
SELECT is((SELECT array_agg(policyname::text ORDER BY policyname::text) FROM pg_policies WHERE schemaname = 'homecollection' AND roles = ARRAY['lims_owner']::name[]), ARRAY['handover_items__select__owner_only','handover_items__update__owner_only','visits__select__owner_only','visits__update__owner_only'], 'C17 check 3 / §4.2: exactly the 4 owner policies TO lims_owner');
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'homecollection' AND tablename <> 'event_inbox' AND roles <> ARRAY['lims_app']::name[] AND policyname !~ '__owner_only$'), 0, 'C17 check 3: every non-lims_app policy is an __owner_only policy');
SELECT is((SELECT array_agg(tablename::text || '.' || cmd) FROM pg_policies WHERE schemaname = 'homecollection' AND roles = ARRAY['lims_app']::name[] AND cmd = 'DELETE'), ARRAY['visit_locations.DELETE'], 'C17 check 3 / P-18(c): the only lims_app DELETE policy is on visit_locations');
SELECT matches((SELECT qual FROM pg_policies WHERE schemaname = 'homecollection' AND policyname = 'visit_locations__delete__tenant_centre'), 'current_actor_type\(\)[^=]*= ''system''::text', 'C17 check 3 / P-18(c): DELETE admits the system actor only');
SELECT matches((SELECT qual FROM pg_policies WHERE schemaname = 'homecollection' AND policyname = 'visit_locations__delete__tenant_centre'), 'expires_at < now\(\)', 'C17 check 3 / P-18(c): DELETE only expired rows');
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'homecollection' AND tablename = rt.t AND cmd = 'UPDATE' AND roles = ARRAY['lims_app']::name[]) > 0, u, 'C17 check 3: UPDATE policy on homecollection.' || t || ' iff a lims_app UPDATE grant exists') FROM rt;
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'homecollection' AND tablename <> 'event_inbox' AND roles = ARRAY['lims_app']::name[] AND NOT (coalesce(qual, '') || coalesce(with_check, '')) LIKE '%current_tenant_id%'), 0, 'C17 check 3: tenant predicate in every lims_app policy');
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'homecollection' AND tablename IN ('settings','booking_refs','devices','sync_batches') AND NOT (coalesce(qual, '') || coalesce(with_check, '')) LIKE '%is_staff_or_system%'), 0, 'C17 check 3 / 08 A17 P-16: every tenant-scope policy carries app.is_staff_or_system()');
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'homecollection' AND tablename = rt.t AND roles = ARRAY['lims_app']::name[] AND (coalesce(qual, '') || coalesce(with_check, '')) LIKE '%current_centre_ids%') > 0, ce, 'C17 check 3: homecollection.' || t || ' is centre-scoped iff §4.1 puts it in centre_tables / the handover pair') FROM rt;
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'homecollection' AND (coalesce(qual, '') || coalesce(with_check, '')) ~ 'current_centre_ids' AND (coalesce(qual, '') || coalesce(with_check, '')) !~ 'uuid\[\]'), 0, 'C17 check 3 / 08 A16.1: every centre predicate uses the ::uuid[] cast');
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'homecollection' AND (coalesce(qual, '') || coalesce(with_check, '')) ~ '(^|[ (])true($|[ )])'), 0, 'C17 check 3 / REQ-SEC-016: no USING (true)');
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'homecollection' AND tablename <> 'event_inbox' AND policyname !~ ('^' || tablename || '__(select|insert|update|delete)__[a-z_]+$')), 0, 'C17 check 3: policy names are <table>__<cmd>__<scope>');
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'homecollection' AND tablename <> 'event_inbox' AND policyname !~ ('__' || lower(cmd) || '__')), 0, 'C17 check 3: the command in the policy name matches the policy command');
SELECT matches(qual, 'app\.maintenance''::text, true\) = ''homecollection_anonymise_retired_visits''::text', 'C17 check 3 / A12.2: owner policy ' || policyname || ' is gated by the app.maintenance GUC') FROM pg_policies WHERE schemaname = 'homecollection' AND roles = ARRAY['lims_owner']::name[];
SELECT matches((SELECT with_check FROM pg_policies WHERE schemaname = 'homecollection' AND policyname = 'handover_items__update__owner_only'), 'barcode = ''ANONYMISED''::text', 'C17 check 3: the owner may write only the ANONYMISED barcode');
SELECT matches((SELECT qual FROM pg_policies WHERE schemaname = 'homecollection' AND policyname = 'handovers__select__tenant_centre'), 'to_centre_id', 'C17 check 3 / §1: handovers are visible from the receiving centre');
SELECT is((SELECT with_check ~ 'to_centre_id' FROM pg_policies WHERE schemaname = 'homecollection' AND policyname = 'handovers__insert__tenant_centre'), false, 'C17 check 3 / §4.1 (2): handovers are written by the from (centre_id) side only');

-- C17 check 4: grant matrix (AC-0B-4.2 / 4.3; §4.1): S I U on 10 tables, S I on the 4 append-only, S I D on visit_locations, S on g_cs_reasons; DELETE nowhere else (CI assertion of §4.1)
SELECT is(ARRAY[has_table_privilege('lims_app', 'homecollection.' || t, 'SELECT'), has_table_privilege('lims_app', 'homecollection.' || t, 'INSERT'), has_table_privilege('lims_app', 'homecollection.' || t, 'UPDATE'), has_table_privilege('lims_app', 'homecollection.' || t, 'DELETE')],
  ARRAY[true, true, u, d], 'C17 check 4 / AC-0B-4.1 / 4.2: lims_app privileges on homecollection.' || t || ' = §4.1 (S I' || CASE WHEN u THEN ' U' ELSE '' END || CASE WHEN d THEN ' D' ELSE '' END || ')') FROM rt;
SELECT is(ARRAY[has_table_privilege('lims_app', 'homecollection.' || t, 'SELECT'), has_table_privilege('lims_app', 'homecollection.' || t, 'INSERT'), has_table_privilege('lims_app', 'homecollection.' || t, 'UPDATE'), has_table_privilege('lims_app', 'homecollection.' || t, 'DELETE')],
  ARRAY[true, false, false, false], 'C17 check 4 / AC-0B-4.3: lims_app only SELECTs homecollection.' || t) FROM rg;
SELECT is((SELECT count(*)::int FROM pg_class c WHERE c.relnamespace = 'homecollection'::regnamespace AND c.relkind = 'r' AND has_table_privilege('lims_app', c.oid, 'DELETE')), 1, 'C17 check 4 / §4.1 CI line: has_table_privilege(lims_app, t, DELETE) = false for every homecollection table except visit_locations');
SELECT is(has_table_privilege('lims_app', 'homecollection.' || t, 'TRUNCATE') OR has_table_privilege('lims_app', 'homecollection.' || t, 'REFERENCES') OR has_table_privilege('lims_app', 'homecollection.' || t, 'TRIGGER'), false, 'C17 check 4: no TRUNCATE / REFERENCES / TRIGGER on homecollection.' || t) FROM rt;
SELECT is(has_table_privilege('lims_analytics', 'homecollection.' || x.t, p), false, 'C17 check 4: lims_analytics has no ' || p || ' on homecollection.' || x.t) FROM (SELECT t FROM rt UNION ALL SELECT t FROM rg) x, unnest(ARRAY['SELECT','INSERT','UPDATE','DELETE']) p;
SELECT is((SELECT count(*)::int FROM information_schema.role_table_grants WHERE table_schema = 'homecollection' AND grantee IN ('PUBLIC','anon','authenticated','service_role')), 0, 'C17 check 4: nothing granted to PUBLIC / anon / authenticated / service_role');

-- C17 check 5: indexes and constraints (§4): tenant_id leads every index except the primary keys and the G table; __p_ indexes partial; UNIQUE (tenant_id, id) everywhere; tenant FK; composite FKs; no mandatory-column exception
SELECT is((regexp_match(pg_get_indexdef(i.indexrelid), '\(([^,)]+)'))[1], 'tenant_id', 'C17 check 5: index ' || c.relname || ' leads with tenant_id')
  FROM pg_index i JOIN pg_class c ON c.oid = i.indexrelid JOIN pg_class t ON t.oid = i.indrelid
  WHERE t.relnamespace = 'homecollection'::regnamespace AND t.relname NOT LIKE 'g\_%' AND t.relname <> 'event_inbox' AND NOT i.indisprimary;
SELECT is((SELECT count(*)::int FROM pg_indexes WHERE schemaname = 'homecollection' AND indexname ~ '__p_(uq|idx)$' AND indexdef NOT LIKE '% WHERE %'), 0, 'C17 check 5: every __p_ index is partial');
SELECT is((SELECT count(*)::int FROM pg_indexes WHERE schemaname = 'homecollection' AND tablename <> 'event_inbox' AND indexname NOT IN (SELECT conname FROM pg_constraint WHERE connamespace = 'homecollection'::regnamespace)), 32, 'C17 check 5: exactly the 32 spec indexes beyond the constraint-backed ones (no extra index)');
SELECT is((SELECT count(*)::int FROM pg_constraint WHERE conrelid = ('homecollection.' || t)::regclass AND contype = 'u' AND pg_get_constraintdef(oid) = 'UNIQUE (tenant_id, id)'), 1, 'C17 check 5 / 04 D8: UNIQUE (tenant_id, id) on homecollection.' || t) FROM rt;
SELECT is((SELECT count(*)::int FROM pg_constraint WHERE conrelid = ('homecollection.' || t)::regclass AND contype = 'f' AND confrelid = 'core.tenants'::regclass AND pg_get_constraintdef(oid) = 'FOREIGN KEY (tenant_id) REFERENCES core.tenants(id)'), 1, 'C17 check 5 / C0 §9 rule 1: tenant FK -> core.tenants on homecollection.' || t) FROM rt;
SELECT is((SELECT count(*)::int FROM pg_constraint c WHERE c.contype = 'f' AND c.conrelid IN (SELECT oid FROM pg_class WHERE relnamespace = 'homecollection'::regnamespace AND relname NOT LIKE 'g\_%' AND relname <> 'event_inbox')
  AND cardinality(c.conkey) = 1 AND c.confrelid <> 'core.tenants'::regclass), 0, 'C17 check 5: every FK except the tenant FK is composite (tenant_id, x) (02-CV §5.4)');
SELECT is((SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid = 'homecollection.booking_refs'::regclass AND conname = 'booking_refs__visit__fk'), 'FOREIGN KEY (tenant_id, visit_id) REFERENCES homecollection.visits(tenant_id, id)', 'C17 check 5: booking_refs -> visits FK added after visits exists (§4 comment)');
SELECT is((SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid = 'homecollection.mutations'::regclass AND conname = 'mutations__batch__fk'), 'FOREIGN KEY (tenant_id, batch_id) REFERENCES homecollection.sync_batches(tenant_id, id) DEFERRABLE INITIALLY DEFERRED', 'C17 check 5: mutations -> sync_batches is DEFERRABLE INITIALLY DEFERRED (TRD §6.3 step 6)');
SELECT is((SELECT count(*)::int FROM pg_attribute WHERE attrelid = 'homecollection.visit_specimens'::regclass AND attname = 'barcode' AND NOT attisdropped), 0, 'C17 check 5 / review #2: visit_specimens never persists a barcode');
SELECT is((SELECT count(*)::int FROM pg_attribute a WHERE a.attrelid = ('homecollection.' || t)::regclass AND a.attnum > 0 AND NOT a.attisdropped AND a.attname = ANY (
    CASE cls WHEN 'M' THEN ARRAY['id','tenant_id','created_at','created_by','updated_at','updated_by','version','is_active'] WHEN 'C' THEN ARRAY['id','tenant_id','created_at','created_by','updated_at','updated_by','version']
             WHEN 'A' THEN ARRAY['id','tenant_id','created_at','created_by'] ELSE ARRAY['id','tenant_id','created_at','expires_at'] END)),
  CASE cls WHEN 'M' THEN 8 WHEN 'C' THEN 7 WHEN 'A' THEN 4 ELSE 4 END, 'C17 check 5 / §1 P-18(b): homecollection.' || t || ' carries every class-' || cls || ' mandatory column (no exceptions)') FROM rt;
SELECT is((SELECT count(*)::int FROM pg_attribute WHERE attrelid = 'homecollection.g_cs_reasons'::regclass AND attnum > 0 AND NOT attisdropped AND attname = 'tenant_id'), 0, 'C17 check 5: g_cs_reasons is global (no tenant_id)');
SELECT is((SELECT pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid = 'homecollection.g_cs_reasons'::regclass AND conname = 'g_cs_reasons__set_code__uq'), 'UNIQUE (set_code, code)', 'C17 check 5: g_cs_reasons (set_code, code) unique (§1)');

-- C17 check 6: triggers, functions, audit (AC-0B-4.1, 5.1, 5.2, 5.3): 6 mutable-column triggers + 2 C0 transition guards, 10 audit triggers (class M / C)
SELECT is((SELECT count(*)::int FROM pg_trigger tg WHERE tg.tgrelid = ('homecollection.' || t)::regclass AND NOT tg.tgisinternal AND tg.tgname = t || '__audit' AND tg.tgfoid = 'app.tg_row_audit'::regproc), CASE WHEN aud THEN 1 ELSE 0 END, 'C17 check 6 / AC-0B-5.1: audit trigger on homecollection.' || t || ' iff class M / C') FROM rt;
SELECT is((SELECT count(*)::int FROM pg_trigger tg WHERE tg.tgrelid IN (SELECT oid FROM pg_class WHERE relnamespace = 'homecollection'::regnamespace) AND NOT tg.tgisinternal AND tg.tgname LIKE '%\_\_audit'), 10, 'C17 check 6 / AC-0B-5.3: 10 audit triggers (4 class M + 6 class C); none on class A / E / G');
SELECT is((SELECT array_agg(tgname::text ORDER BY tgname::text) FROM pg_trigger WHERE tgrelid IN (SELECT oid FROM pg_class WHERE relnamespace = 'homecollection'::regnamespace) AND NOT tgisinternal AND tgname LIKE '%\_\_mutable\_columns'),
  ARRAY['collections__mutable_columns','handover_items__mutable_columns','handovers__mutable_columns','visit_flags__mutable_columns','visit_specimens__mutable_columns','visits__mutable_columns'], 'C17 check 6 / AC-0B-4.1: the 6 spec immutability triggers on the class C tables');
SELECT is((SELECT tgfoid::regproc::text FROM pg_trigger WHERE tgrelid = ('homecollection.' || t)::regclass AND tgname = t || '__mutable_columns'), 'app.enforce_mutable_columns', 'C17 check 6: homecollection.' || t || ' uses the C0 immutability trigger') FROM unnest(ARRAY['visits','visit_specimens','collections','handovers','handover_items','visit_flags']) t;
SELECT matches(pg_get_triggerdef(oid), 'WHEN .*CURRENT_USER = ''lims_owner''','C17 check 6 / §4: handover_items__mutable_columns is skipped only for the owner under the maintenance GUC') FROM pg_trigger WHERE tgrelid = 'homecollection.handover_items'::regclass AND tgname = 'handover_items__mutable_columns';
SELECT is((SELECT count(*)::int FROM pg_trigger tg WHERE tg.tgrelid = ('homecollection.' || x.t)::regclass AND NOT tg.tgisinternal AND tg.tgname NOT LIKE '%\_\_audit' AND tg.tgname NOT LIKE '%\_\_mutable\_columns' AND (tg.tgtype & 2) = 2 AND (tg.tgtype & 16) = 16 AND (tg.tgtype & 1) = 1), 1, 'C17 check 6: homecollection.' || x.t || ' has its C0 transition guard (BEFORE UPDATE FOR EACH ROW)') FROM (VALUES ('visits'),('collections')) x(t);
SELECT is((SELECT count(*)::int FROM pg_trigger WHERE tgrelid IN (SELECT oid FROM pg_class WHERE relnamespace = 'homecollection'::regnamespace) AND NOT tgisinternal AND tgname NOT LIKE '%\_\_audit' AND tgrelid <> 'homecollection.event_inbox'::regclass), 8, 'C17 check 6: 6 mutable-column + 2 transition triggers, nothing else');
SELECT is((SELECT prosecdef FROM pg_proc WHERE oid = 'homecollection.visits__transition_guard'::regproc), false, 'C17 check 6 / 04 D7: homecollection.visits__transition_guard is SECURITY INVOKER (no inventory row)');
SELECT is((SELECT proconfig FROM pg_proc WHERE oid = 'homecollection.visits__transition_guard'::regproc), ARRAY['search_path=""'], 'C17 check 6: visits__transition_guard has search_path = empty');
SELECT is((SELECT count(*)::int FROM pg_proc WHERE pronamespace = 'homecollection'::regnamespace AND prosecdef), 0, 'C17 check 6: no SECURITY DEFINER function in schema homecollection (the visit_locations purge is a policy, §4.1 (3))');

-- C17 check 7: DEFINER inventory, EXECUTE ACLs, FK direction (AC-0B-6.1 / 6.2 / 6.3; REQ-SEC-031, REQ-SEC-020)
SELECT is((SELECT count(*)::int FROM pg_proc WHERE oid = 'app.homecollection_anonymise_retired_visits(timestamptz)'::regprocedure AND prosecdef AND pg_get_userbyid(proowner) = 'lims_owner' AND proconfig = ARRAY['search_path=""'] AND provolatile = 'v'), 1, 'C17 check 7 / AC-0B-6.3: the anonymise function is SECURITY DEFINER, VOLATILE, owned by lims_owner, search_path = empty');
SELECT is(has_function_privilege('lims_worker', 'app.homecollection_anonymise_retired_visits(timestamptz)', 'EXECUTE'), true, 'C17 check 7 / §4.2: lims_worker may EXECUTE the anonymise function');
SELECT is(has_function_privilege(r, 'app.homecollection_anonymise_retired_visits(timestamptz)', 'EXECUTE'), false, 'C17 check 7 / 08 A12.1: ' || r || ' may NOT execute the anonymise function') FROM unnest(ARRAY['lims_analytics']) r;
SELECT is((SELECT coalesce(proacl::text, '') ~ '(^\{|,)=X' FROM pg_proc WHERE oid = 'app.homecollection_anonymise_retired_visits(timestamptz)'::regprocedure), false, 'C17 check 7: EXECUTE revoked from PUBLIC');
SELECT is((SELECT count(*)::int FROM pg_proc WHERE prosecdef AND ((pronamespace = 'app'::regnamespace AND proname LIKE 'homecollection_%') OR pronamespace = 'homecollection'::regnamespace)), 1, 'C17 check 7: exactly 1 DEFINER function of C17 (matches the 1 inventory row)');
SELECT is((SELECT array_agg(DISTINCT n.nspname::text ORDER BY n.nspname::text) FROM pg_constraint c JOIN pg_class r ON r.oid = c.confrelid JOIN pg_namespace n ON n.oid = r.relnamespace WHERE c.contype = 'f' AND c.conrelid IN (SELECT oid FROM pg_class WHERE relnamespace = 'homecollection'::regnamespace)),
  ARRAY['core','frontdesk','homecollection','lab'], 'C17 check 7 / AC-0B-6.2: homecollection FKs point into homecollection, core, frontdesk, lab only (01 §5 R3; none into billing / engagement)');
SELECT is((SELECT count(*)::int FROM pg_constraint c JOIN pg_class r ON r.oid = c.confrelid WHERE c.contype = 'f' AND r.relnamespace = 'homecollection'::regnamespace AND c.conrelid NOT IN (SELECT oid FROM pg_class WHERE relnamespace = 'homecollection'::regnamespace)), 0, 'C17 check 7 / AC-0B-6.2: nothing references homecollection from another schema');
SELECT is((SELECT count(*)::int FROM pg_class c WHERE c.relnamespace = 'homecollection'::regnamespace AND c.relkind = 'r' AND c.relname IN (SELECT t FROM rt)), 15, 'C17 check 7 / AC-0B-6.1: all 15 tenant tables exist after the migrations applied in order');

-- C17 check 8: views (AC-0B-6.4; IC §6: none) and seeds (§2: 8 sets, 40 rows, global only, D-130)
SELECT is((SELECT count(*)::int FROM pg_class WHERE relnamespace = 'homecollection'::regnamespace AND relname LIKE 'v\_pub\_%'), 0, 'C17 check 8 / AC-0B-6.4: no v_pub_* view (the view column contract is vacuous: IC §6 lists none for homecollection)');
SELECT is((SELECT count(*)::int FROM homecollection.g_cs_reasons), 40, 'C17 check 8 / §2: 40 reason codes seeded');
SELECT is((SELECT array_agg(set_code ORDER BY set_code) FROM (SELECT DISTINCT set_code FROM homecollection.g_cs_reasons) s), ARRAY['flag_resolutions','review_reasons','revisit_reasons','specimen_not_collected_reasons','unassign_reasons','visit_cancel_reasons','visit_fail_reasons','wipe_reasons'], 'C17 check 8 / §2: the 8 sets');
SELECT is((SELECT count(*)::int FROM homecollection.g_cs_reasons WHERE code = 'other' AND NOT requires_text), 0, 'C17 check 8 / §2: every "other" requires text (the † marker)');
SELECT is((SELECT count(*)::int FROM homecollection.g_cs_reasons WHERE requires_text), 8, 'C17 check 8 / §2: exactly the 8 † codes require text');
SELECT is((SELECT count(*)::int FROM homecollection.g_cs_reasons WHERE system <> 'lims' OR system_version <> '1' OR NOT is_active), 0, 'C17 check 8 / §2: system = lims, system_version = 1, active');
SELECT is((SELECT array_agg(code ORDER BY sort_order) FROM homecollection.g_cs_reasons WHERE set_code = 'wipe_reasons'), ARRAY['lost','stolen','retired','reassigned','other'], 'C17 check 8 / §2: wipe_reasons in spec order');
SELECT is((SELECT count(*)::int FROM homecollection.settings) + (SELECT count(*)::int FROM homecollection.visits) + (SELECT count(*)::int FROM homecollection.devices) + (SELECT count(*)::int FROM homecollection.collections), 0, 'C17 check 8 / §7: no tenant data seeded by the migrations (fixtures belong to packages/test-fixtures)');
SELECT is((SELECT count(*)::int FROM pg_policies WHERE schemaname = 'storage' AND policyname LIKE 'homecollection%'), 0, 'C17 check 8: no storage policy is created by SQL');

SELECT * FROM finish();
